--
-- Structure de la table `users`
--

CREATE TABLE `users` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `role` varchar(255) NOT NULL DEFAULT 'user',
  `nom` varchar(255) NOT NULL,
  `prenom` varchar(255) NOT NULL,
  `phone` varchar(255) DEFAULT NULL,
  `alias` varchar(255) NOT NULL,
  `numero_bancaire` varchar(255) NOT NULL,
  `card_number` varchar(19) NOT NULL,
  `iban` varchar(255) NOT NULL,
  `bic` varchar(255) NOT NULL,
  `date_exp` date DEFAULT NULL,
  `cvv` varchar(4) DEFAULT NULL,
  `solde` decimal(10,2) NOT NULL DEFAULT 0.00,
  `piece_identite` varchar(255) DEFAULT NULL,
  `avis_imposition` varchar(255) DEFAULT NULL,
  `photo_carte_identite` varchar(255) DEFAULT NULL,
  `profile_photo_url` varchar(255) DEFAULT NULL,
  `account_status` tinyint(4) NOT NULL DEFAULT 0 COMMENT '0=inactive, 1=active',
  `email` varchar(255) NOT NULL,
  `devise` varchar(255) NOT NULL DEFAULT '€',
  `card_active` tinyint(1) NOT NULL DEFAULT 0,
  `card_attente` tinyint(1) NOT NULL DEFAULT 0,
  `card_frozen` tinyint(1) NOT NULL DEFAULT 0,
  `email_verified_at` timestamp NULL DEFAULT NULL,
  `phone_verified_at` timestamp NULL DEFAULT NULL,
  `password` varchar(255) NOT NULL,
  `kyc_status` enum('pending','in_progress','approved','rejected','expired') NOT NULL DEFAULT 'pending',
  `kyc_submitted_at` timestamp NULL DEFAULT NULL,
  `kyc_approved_at` timestamp NULL DEFAULT NULL,
  `kyc_rejection_reason` text DEFAULT NULL,
  `ip_address` varchar(255) DEFAULT NULL,
  `last_ip_address` varchar(255) DEFAULT NULL,
  `country` varchar(255) DEFAULT NULL,
  `address_line` varchar(255) DEFAULT NULL,
  `city` varchar(255) DEFAULT NULL,
  `postal_code` varchar(32) DEFAULT NULL,
  `date_naissance` date DEFAULT NULL,
  `nationalite` varchar(128) DEFAULT NULL,
  `numero_identification` varchar(64) DEFAULT NULL,
  `last_country` varchar(255) DEFAULT NULL,
  `is_blocked` tinyint(1) NOT NULL DEFAULT 0,
  `is_online` tinyint(1) NOT NULL DEFAULT 0,
  `remember_token` varchar(100) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `card_amount` decimal(12,2) NOT NULL DEFAULT 0.00,
  `card_type` varchar(32) NOT NULL DEFAULT 'platinum',
  `birth_date` date DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

